import{_ as n,I as t,o as r,c as d,b6 as i,j as p,J as e,w as o}from"./chunks/framework.BUXTSoD9.js";const _=JSON.parse('{"title":"モダン AI 画像生成 SaaS 開発実践","description":"","frontmatter":{},"headers":[],"relativePath":"ja-jp/stage-2/assignments/modern-landing-page/index.md","filePath":"ja-jp/stage-2/assignments/modern-landing-page/index.md"}'),h={name:"ja-jp/stage-2/assignments/modern-landing-page/index.md"},c={style:{margin:"32px 0"}};function b(g,a,k,u,m,f){const l=t("StepBar"),s=t("ClientOnly");return r(),d("div",null,[a[0]||(a[0]=i('<h1 id="モダン-ai-画像生成-saas-開発実践" tabindex="-1">モダン AI 画像生成 SaaS 開発実践 <a class="header-anchor" href="#モダン-ai-画像生成-saas-開発実践" aria-label="Permalink to “モダン AI 画像生成 SaaS 開発実践”">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to “概要”">​</a></h2><p>本実践プロジェクトでは、実際の PRD（要件定義書）に基づき、Midjourney の体験を参考にした AI 画像生成 SaaS 製品をゼロから構築します。要件分析、プロジェクト分割、反復開発、結合テストとデプロイまでの全プロセスを経験します。</p><p>これは Stage 2 の総合実践セクションです。これまでの章で、フロントエンドページ設計、バックエンドインターフェース開発、データベース操作、決済統合などの個別スキルを学びました。このプロジェクトでは、それらすべてを統合し、実行可能な製品プロトタイプを納品します。</p><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to “前提知識”">​</a></h2><p>本プロジェクトを開始する前に、以下の内容を習得している必要があります：</p><ul><li>フロントエンドページ設計とコンポーネントライブラリの使用（<a href="./../../frontend/ui-design/">UI 設計</a>、<a href="./../../frontend/modern-component-library/">モダンコンポーネントライブラリ</a>）</li><li>バックエンドインターフェースの設計と開発（<a href="./../../backend/ai-interface-code/">インターフェースコードの記述</a>）</li><li>データベースの基礎と Supabase（<a href="./../../backend/database-supabase/">データベースから Supabase へ</a>）</li><li>決済統合（<a href="./../../backend/stripe-payment/">Stripe 決済システム</a>）</li><li>Git ワークフローとデプロイ（<a href="./../../backend/git-workflow/">Git と GitHub</a>、<a href="./../../backend/zeabur-deployment/">Web アプリケーションのデプロイ</a>）</li></ul><h2 id="学習目標" tabindex="-1">学習目標 <a class="header-anchor" href="#学習目標" aria-label="Permalink to “学習目標”">​</a></h2><p>本実践を完了すると、以下のことができるようになります：</p><ol><li>実際の PRD を読み解き、開発タスクリストを抽出する</li><li>PRD に基づいてモジュールを分割し、段階的な推進計画を策定する</li><li>AI を活用してフロントエンドスケルトンの構築とバックエンドインターフェース開発を完了する</li><li>各モジュールを検証し、反復的に最適化する</li><li>エンドツーエンドの結合テストを完了し、プロジェクトを「動く」状態から「納品可能」な状態に引き上げる</li></ol><h2 id="プロジェクト概要" tabindex="-1">プロジェクト概要 <a class="header-anchor" href="#プロジェクト概要" aria-label="Permalink to “プロジェクト概要”">​</a></h2><p>構築する製品は、モダンな AI 画像生成 SaaS プラットフォームであり、3つのサブシステムで構成されます：</p><table tabindex="0"><thead><tr><th>サブシステム</th><th>責務</th></tr></thead><tbody><tr><td><strong>公式サイト</strong></td><td>製品紹介、料金プラン、FAQ、登録コンバージョン</td></tr><tr><td><strong>ユーザーワークスペース</strong></td><td>Prompt 入力、画像生成、ギャラリー、クレジット、プラン、コミュニティ交流</td></tr><tr><td><strong>管理画面</strong></td><td>ユーザー管理、タスク管理、決済管理、コンテンツ審査、SaaS 指標、システムモニタリング</td></tr></tbody></table><p>バックエンドは以下のコア機能をサポートする必要があります：ユーザー認証、画像生成タスク、OSS オブジェクトストレージ、クレジットとプラン決済、画像ソーシャルインタラクション、運用データモニタリング。</p><div class="tip custom-block"><p class="custom-block-title">PRD 入口</p><p>本プロジェクトの要件定義書は GitHub にあります： <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-cn/stage-2/assignments/modern-landing-page/PRD.md" target="_blank" rel="noreferrer">PRD を確認</a></p></div>',15)),p("div",c,[e(s,null,{default:o(()=>[e(l,{active:0,items:[{title:"要件分析",description:"PRD を読み、ページ、モジュール、データモデルと境界を抽出"},{title:"スケルトン構築",description:"AI で3つのフロントエンドスケルトン（www / app / admin）を生成"},{title:"反復開発",description:"モジュールごとにインターフェース、権限、決済、モニタリングを追加"},{title:"結合・デプロイ",description:"エンドツーエンドで動作確認し、デプロイしてデモを準備"}]})]),_:1})]),a[1]||(a[1]=i(`<h2 id="第1部-要件分析" tabindex="-1">第1部：要件分析 <a class="header-anchor" href="#第1部-要件分析" aria-label="Permalink to “第1部：要件分析”">​</a></h2><h3 id="_1-1-prd-の読解" tabindex="-1">1.1 PRD の読解 <a class="header-anchor" href="#_1-1-prd-の読解" aria-label="Permalink to “1.1 PRD の読解”">​</a></h3><p>PRD 文書を開き、以下の質問に重点的に答えてください：</p><ul><li>システムにはいくつの入口がありますか？それぞれどのページをカバーしていますか？</li><li>各ページのコア機能は何ですか？</li><li>バックエンドにはどのモジュールとデータベーステーブルが含まれていますか？</li><li>MVP の範囲は何ですか？初版で何を作り、何を作らないか？</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>上記の質問に明確な答えがない場合は、コードを書き始めないでください。要件の理解が不明確であることは、手戻りの最も一般的な原因です。</p></div><h3 id="_1-2-システムアーキテクチャの確認" tabindex="-1">1.2 システムアーキテクチャの確認 <a class="header-anchor" href="#_1-2-システムアーキテクチャの確認" aria-label="Permalink to “1.2 システムアーキテクチャの確認”">​</a></h3><p>PRD の記述に基づいて、システムの全体アーキテクチャを整理します：</p><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; web[&quot;公式サイト&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; app[&quot;ユーザーワークスペース&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd --&gt; admin[&quot;管理画面&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; auth[&quot;認証&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app --&gt; gen[&quot;画像生成タスク&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gen --&gt; oss[&quot;OSS オブジェクトストレージ&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gen --&gt; db[&quot;データベース&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  billing[&quot;決済とプラン&quot;] --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  social[&quot;シェア / いいね / コメント / 転送&quot;] --&gt; db</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; analytics[&quot;SaaS 指標ダッシュボード&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  admin --&gt; observability[&quot;API / DB / Provider モニタリング&quot;]</span></span></code></pre></div><p>自分の言葉でアーキテクチャ図を描き直し、システムの理解が完全であることを確認することをお勧めします。</p><h2 id="第2部-プロジェクトスケルトンの構築" tabindex="-1">第2部：プロジェクトスケルトンの構築 <a class="header-anchor" href="#第2部-プロジェクトスケルトンの構築" aria-label="Permalink to “第2部：プロジェクトスケルトンの構築”">​</a></h2><h3 id="_2-1-フロントエンドページの生成" tabindex="-1">2.1 フロントエンドページの生成 <a class="header-anchor" href="#_2-1-フロントエンドページの生成" aria-label="Permalink to “2.1 フロントエンドページの生成”">​</a></h3><p>AI を使用して、まずすべてのページの基本構造とモックデータを生成します。このステップの目標は、情報アーキテクチャとルーティングを構築することであり、実際のインターフェースに接続する必要はありません。</p><p>プロンプトの参考例：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>現在の PRD に基づいて、モダンな AI 画像生成 SaaS のフロントエンドスケルトンを生成してください。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要件：</span></span>
<span class="line"><span>1. 3つの入口に分ける：www、app、admin</span></span>
<span class="line"><span>2. 公式サイトには：ホーム、料金プラン、FAQ</span></span>
<span class="line"><span>3. app には：ログイン、登録、生成ワークスペース、ギャラリー、プラン、クレジット、コミュニティ、作品詳細、個人センター</span></span>
<span class="line"><span>4. admin には：管理画面ホーム、ユーザー管理、タスク管理、コンテンツ管理、プラン管理、決済オーダー、運用設定、SaaS 指標、システムモニタリング</span></span>
<span class="line"><span>5. まずページ構造とモックデータのみを生成し、実際のインターフェースには接続しない</span></span>
<span class="line"><span>6. Midjourney を参考に、シンプルでモダン、製品感のあるスタイルにする</span></span></code></pre></div><h3 id="_2-2-ページ構造の検証" tabindex="-1">2.2 ページ構造の検証 <a class="header-anchor" href="#_2-2-ページ構造の検証" aria-label="Permalink to “2.2 ページ構造の検証”">​</a></h3><p>スケルトン生成後、各項目をチェック：</p><ul><li>[ ] 3つの入口のルーティングが独立しているか（<code>/</code>、<code>/app</code>、<code>/admin</code>）</li><li>[ ] ページ数が PRD と一致しているか</li><li>[ ] 各ページが正常にアクセス・ナビゲーションできるか</li><li>[ ] モックデータが基本的な UI の状態を表現しているか（リスト、空の状態、フォームなど）</li></ul><h2 id="第3部-反復開発" tabindex="-1">第3部：反復開発 <a class="header-anchor" href="#第3部-反復開発" aria-label="Permalink to “第3部：反復開発”">​</a></h2><h3 id="_3-1-モジュールごとの推進" tabindex="-1">3.1 モジュールごとの推進 <a class="header-anchor" href="#_3-1-モジュールごとの推進" aria-label="Permalink to “3.1 モジュールごとの推進”">​</a></h3><p>スケルトンをベースに、以下の順序でモジュールごとに機能を追加します：</p><ol><li><strong>認証</strong>：登録、ログイン、ロールの区別</li><li><strong>データベース</strong>：データテーブルの作成、読み書きインターフェース</li><li><strong>コア業務</strong>：画像生成タスク、結果の保存</li><li><strong>OSS ストレージ</strong>：画像のアップロードとアクセス</li><li><strong>決済</strong>：プラン、クレジット、Stripe 統合</li><li><strong>ソーシャルインタラクション</strong>：シェア、いいね、コメント</li><li><strong>管理画面</strong>：ユーザー管理、タスク管理、コンテンツ審査</li><li><strong>データモニタリング</strong>：SaaS 指標ダッシュボード、システムモニタリング</li></ol><p>各モジュールの完了後、以下の表で自己チェック：</p><table tabindex="0"><thead><tr><th>チェック項目</th><th>検証方法</th></tr></thead><tbody><tr><td>ページの一致性</td><td>ページ数、入口、機能が PRD に合致しているか</td></tr><tr><td>インターフェースの正確性</td><td>リクエストパラメータ、返却構造、ステータス処理が適切か</td></tr><tr><td>権限の分離</td><td>一般ユーザーと管理者が相互に分離されているか</td></tr><tr><td>データの整合性</td><td>データベース、OSS、決済、クレジットが一致しているか</td></tr><tr><td>デモ可能性</td><td>他の人に完全な業務チェーンをデモできるか</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>AI が生成した内容が PRD から逸脱していることに気づいた場合は、ページ全体をやり直すのではなく、具体的なモジュールの修正を指示してください。</p></div><h3 id="_3-2-ロールと役割分担" tabindex="-1">3.2 ロールと役割分担 <a class="header-anchor" href="#_3-2-ロールと役割分担" aria-label="Permalink to “3.2 ロールと役割分担”">​</a></h3><p>反復開発の過程では、3つのロールを同時に演じる必要があります：</p><ul><li><strong>プロダクトマネージャー</strong>：各モジュールの機能が PRD に合致しているかを確認</li><li><strong>テックリード</strong>：実装方法が適切であるかを確認</li><li><strong>テストエンジニア</strong>：機能が正しく動作するかを確認</li></ul><h2 id="第4部-結合テストとデプロイ" tabindex="-1">第4部：結合テストとデプロイ <a class="header-anchor" href="#第4部-結合テストとデプロイ" aria-label="Permalink to “第4部：結合テストとデプロイ”">​</a></h2><h3 id="_4-1-エンドツーエンドテスト" tabindex="-1">4.1 エンドツーエンドテスト <a class="header-anchor" href="#_4-1-エンドツーエンドテスト" aria-label="Permalink to “4.1 エンドツーエンドテスト”">​</a></h3><p>最終段階の重点は新しいページを追加することではなく、完全な業務チェーンを動作させることです。少なくとも以下のシナリオを検証してください：</p><ul><li>登録 → クレジット購入 → 画像生成 → 履歴確認 → シェアとインタラクション</li><li>管理者のログイン → ユーザーデータの確認 → タスク統計の確認 → システムモニタリングの確認</li></ul><h3 id="_4-2-デプロイ" tabindex="-1">4.2 デプロイ <a class="header-anchor" href="#_4-2-デプロイ" aria-label="Permalink to “4.2 デプロイ”">​</a></h3><p>プロジェクトをパブリックネットワーク環境にデプロイし、以下を確認：</p><ul><li>環境変数の設定が完全であること</li><li>ログインのコールバックアドレスが正しいこと</li><li>決済のコールバックアドレスが正しいこと</li><li>ページにローディング、空の状態、エラーメッセージが欠落していないこと</li></ul><p>デプロイのチュートリアルはこちらを参照してください：<a href="./../../backend/git-workflow/">Git と GitHub ワークフロー</a>、<a href="./../../backend/zeabur-deployment/">Web アプリケーションのデプロイ方法</a>。</p><h2 id="提出物" tabindex="-1">提出物 <a class="header-anchor" href="#提出物" aria-label="Permalink to “提出物”">​</a></h2><p>本プロジェクト完了後、以下の内容を提出してください：</p><ul><li>[ ] アクセス可能なオンラインデモリンク</li><li>[ ] ソースコードリポジトリのリンク（README を含む）</li><li>[ ] PRD 文書</li><li>[ ] コアページのスクリーンショット（公式サイトホーム、生成ワークスペース、ギャラリー、プランページ、管理画面ホーム）</li><li>[ ] 60秒のデモ動画（登録 → 生成 → 確認 → 管理画面を網羅）</li></ul><p>README には少なくとも以下を含めてください：プロジェクト概要、コアページの説明、技術スタック、ローカル起動手順、環境変数リスト。</p><h2 id="評価基準" tabindex="-1">評価基準 <a class="header-anchor" href="#評価基準" aria-label="Permalink to “評価基準”">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>基本要件</th><th>応用要件</th></tr></thead><tbody><tr><td>PRD への整合</td><td>ページ、機能、データ構造が基本的に PRD に合致</td><td>各設計決定と PRD の対応関係を明確に説明できる</td></tr><tr><td>製品完了</td><td>登録 → クレジット購入 → 画像生成 → 履歴確認 → シェアとインタラクションが動作</td><td>決済ステータス、クレジット残高、生成回数のデータが一致</td></tr><tr><td>管理画面の機能</td><td>ユーザー、タスク、決済、コンテンツ管理が閲覧可能</td><td>SaaS 指標ダッシュボードとシステムモニタリングページが完全に利用可能</td></tr><tr><td>エンジニアリング完成度</td><td>フロントエンド、バックエンド、データベース、OSS、決済チェーンが接続済み</td><td>エラー処理、空の状態、ローディング状態がある</td></tr><tr><td>納品品質</td><td>デプロイ可能、実行可能</td><td>README が明確で、デモ動画の構造が完全</td></tr></tbody></table><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to “参考資料”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 設計</a></li><li><a href="./../../frontend/multi-product-ui/">UI 設計仕様を参考にページとボタンを設計</a></li><li><a href="./../../frontend/llm-skills-beautiful/">LLM と Skills でインターフェースを見栄えよくする</a></li><li><a href="./../../frontend/design-to-code/">デザインプロトタイプからプロジェクトコードへ</a></li><li><a href="./../../frontend/modern-component-library/">モダンコンポーネントライブラリでインターフェースをアップデート</a></li><li><a href="./../../backend/database-supabase/">データベースから Supabase へ</a></li><li><a href="./../../backend/ai-interface-code/">大規模言語モデルによるインターフェースコードとインターフェース文書の作成支援</a></li><li><a href="./../../backend/git-workflow/">Git と GitHub ワークフロー</a></li><li><a href="./../../backend/zeabur-deployment/">Web アプリケーションのデプロイ方法</a></li><li><a href="./../../backend/stripe-payment/">Stripe などの決済システムの統合方法</a></li></ul>`,43))])}const P=n(h,[["render",b]]);export{_ as __pageData,P as default};
